class ReturnLoanApiTest {

    @Autowired
    MockMvc mockMvc;

    @Autowired
    ObjectMapper objectMapper;

    @Test
    void returning_a_loan_returns_200_with_the_return_date() throws Exception {
        String memberId = registerMember("박서준");
        String bookId = registerBook();
        String loanId = loanBook(bookId, memberId);

        mockMvc.perform(post("/loans/{loanId}/return", loanId))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.loanId").value(loanId))
                .andExpect(jsonPath("$.returnedAt").value(LocalDate.now().toString()));
    }

    @Test
    void returning_an_already_returned_loan_returns_409() throws Exception {
        String memberId = registerMember("최유진");
        String loanId = loanBook(registerBook(), memberId);

        mockMvc.perform(post("/loans/{loanId}/return", loanId))
                .andExpect(status().isOk());

        mockMvc.perform(post("/loans/{loanId}/return", loanId))
                .andExpect(status().isConflict())
                .andExpect(jsonPath("$.error").value("ALREADY_RETURNED"));
    }

    @Test
    void returning_an_unknown_loan_returns_404() throws Exception {
        mockMvc.perform(post("/loans/{loanId}/return", UUID.randomUUID()))
                .andExpect(status().isNotFound());
    }

    @Test
    void a_returned_book_becomes_available_and_can_be_loaned_again() throws Exception {
        String bookId = registerBook();
        String firstLoanId = loanBook(bookId, registerMember("정하윤"));

        mockMvc.perform(post("/loans/{loanId}/return", firstLoanId))
                .andExpect(status().isOk());

        mockMvc.perform(get("/books/{bookId}", bookId))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.status").value("AVAILABLE"));

        loanBook(bookId, registerMember("윤도현"));
    }

    @Test
    void returned_loans_do_not_count_toward_the_five_loan_limit() throws Exception {
        String memberId = registerMember("강지우");
        String firstLoanId = null;
        for (int i = 0; i < 5; i++) {
            String loanId = loanBook(registerBook(), memberId);
            if (firstLoanId == null) {
                firstLoanId = loanId;
            }
        }

        mockMvc.perform(post("/loans/{loanId}/return", firstLoanId))
                .andExpect(status().isOk());

        loanBook(registerBook(), memberId);
    }

    String registerMember(String name) throws Exception {
        String registered = mockMvc.perform(post("/members")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"name\":\"" + name + "\"}"))
                .andExpect(status().isCreated())
                .andReturn().getResponse().getContentAsString();
        return objectMapper.readTree(registered).get("memberId").asText();
    }

    String registerBook() throws Exception {
        String registered = mockMvc.perform(post("/books")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"title\":\"Refactoring\"}"))
                .andExpect(status().isCreated())
                .andReturn().getResponse().getContentAsString();
        JsonNode book = objectMapper.readTree(registered);
        return book.get("id").asText();
    }

    String loanBook(String bookId, String memberId) throws Exception {
