            countQuery = "select count(l) from LoanJpaEntity l where l.memberId = :memberId and l.returnedAt is null")
    Page<ActiveLoanRow> findActiveLoanRowsByMemberId(@Param("memberId") UUID memberId, Pageable pageable);
}

