package com.example.lending;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.http.MediaType;
import org.springframework.test.web.servlet.MockMvc;

import java.time.LocalDate;
import java.util.UUID;

import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

@SpringBootTest
@AutoConfigureMockMvc
class MemberLoansApiTest {

    @Autowired
    MockMvc mockMvc;

    @Autowired
    ObjectMapper objectMapper;

    @Test
    void active_loans_are_returned_with_book_title_and_dates() throws Exception {
        String memberId = registerMember("김나은");
        String bookId = registerBook("Clean Code");
        String loanId = loanBook(bookId, memberId);

        mockMvc.perform(get("/members/{memberId}/loans", memberId))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.items[0].loanId").value(loanId))
                .andExpect(jsonPath("$.items[0].bookId").value(bookId))
                .andExpect(jsonPath("$.items[0].title").value("Clean Code"))
                .andExpect(jsonPath("$.items[0].loanedAt").value(LocalDate.now().toString()))
                .andExpect(jsonPath("$.items[0].dueAt").value(LocalDate.now().plusDays(14).toString()))
                .andExpect(jsonPath("$.page").value(0))
                .andExpect(jsonPath("$.size").value(20))
                .andExpect(jsonPath("$.totalCount").value(1));
    }

    @Test
    void returned_loans_are_excluded() throws Exception {
        String memberId = registerMember("오세진");
        String returnedLoanId = loanBook(registerBook("Refactoring"), memberId);
        String activeLoanId = loanBook(registerBook("Effective Java"), memberId);

        mockMvc.perform(post("/loans/{loanId}/return", returnedLoanId))
                .andExpect(status().isOk());

        mockMvc.perform(get("/members/{memberId}/loans", memberId))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.items.length()").value(1))
                .andExpect(jsonPath("$.items[0].loanId").value(activeLoanId))
                .andExpect(jsonPath("$.totalCount").value(1));
    }

    @Test
    void page_and_size_slice_the_list_while_total_count_covers_all_active_loans() throws Exception {
        String memberId = registerMember("한지안");
        for (int i = 0; i < 3; i++) {
            loanBook(registerBook("Book " + i), memberId);
        }

        JsonNode firstPage = readBody(get("/members/{memberId}/loans", memberId)
                .param("page", "0")
                .param("size", "2"));
        mockMvc.perform(get("/members/{memberId}/loans", memberId)
                        .param("page", "0")
                        .param("size", "2"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.items.length()").value(2))
                .andExpect(jsonPath("$.page").value(0))
                .andExpect(jsonPath("$.size").value(2))
                .andExpect(jsonPath("$.totalCount").value(3));

        JsonNode secondPage = readBody(get("/members/{memberId}/loans", memberId)
                .param("page", "1")
                .param("size", "2"));
        mockMvc.perform(get("/members/{memberId}/loans", memberId)
                        .param("page", "1")
                        .param("size", "2"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.items.length()").value(1))
                .andExpect(jsonPath("$.page").value(1))
                .andExpect(jsonPath("$.totalCount").value(3));

        // 두 페이지를 합치면 중복 없이 대출 3건이 모두 나와야 한다.
        UUID first = UUID.fromString(firstPage.get("items").get(0).get("loanId").asText());
        UUID second = UUID.fromString(firstPage.get("items").get(1).get("loanId").asText());
        UUID third = UUID.fromString(secondPage.get("items").get(0).get("loanId").asText());
        org.assertj.core.api.Assertions.assertThat(java.util.Set.of(first, second, third)).hasSize(3);
    }

    @Test
    void a_member_without_loans_gets_an_empty_list() throws Exception {
        String memberId = registerMember("서민준");

        mockMvc.perform(get("/members/{memberId}/loans", memberId))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.items.length()").value(0))
                .andExpect(jsonPath("$.totalCount").value(0));
    }

    @Test
    void unknown_member_returns_404() throws Exception {
        mockMvc.perform(get("/members/{memberId}/loans", UUID.randomUUID()))
                .andExpect(status().isNotFound());
    }

    @Test
    void negative_page_or_non_positive_size_returns_400() throws Exception {
        String memberId = registerMember("문보경");

        mockMvc.perform(get("/members/{memberId}/loans", memberId).param("page", "-1"))
                .andExpect(status().isBadRequest());

        mockMvc.perform(get("/members/{memberId}/loans", memberId).param("size", "0"))
                .andExpect(status().isBadRequest());
    }

    JsonNode readBody(org.springframework.test.web.servlet.RequestBuilder request) throws Exception {
        String body = mockMvc.perform(request)
                .andExpect(status().isOk())
                .andReturn().getResponse().getContentAsString();
        return objectMapper.readTree(body);
    }

    String registerMember(String name) throws Exception {
        String registered = mockMvc.perform(post("/members")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"name\":\"" + name + "\"}"))
                .andExpect(status().isCreated())
                .andReturn().getResponse().getContentAsString();
        return objectMapper.readTree(registered).get("memberId").asText();
    }

    String registerBook(String title) throws Exception {
        String registered = mockMvc.perform(post("/books")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"title\":\"" + title + "\"}"))
                .andExpect(status().isCreated())
                .andReturn().getResponse().getContentAsString();
        return objectMapper.readTree(registered).get("id").asText();
    }

    String loanBook(String bookId, String memberId) throws Exception {
        String body = objectMapper.writeValueAsString(new LoanBody(bookId, memberId));
        String loaned = mockMvc.perform(post("/loans").contentType(MediaType.APPLICATION_JSON).content(body))
                .andExpect(status().isCreated())
                .andReturn().getResponse().getContentAsString();
        return objectMapper.readTree(loaned).get("loanId").asText();
    }

    record LoanBody(String bookId, String memberId) {
    }
}

